describe('ChatOrchestrator onError coercion', () => {
  const resolvedSentinel = Symbol('resolved');

  const observeRejection = async (thrown: unknown) => {
    const seen: Error[] = [];
    const orchestrator = createChatOrchestrator(createErrorProvider(thrown), promptBuilder, undefined, {
      hooks: {
        onError: async (_session, error) => {
          seen.push(error);
        },
      },
    });
    const turn = orchestrator.processMessage(createSession('hello'));
    const caught = await turn.then(
      () => resolvedSentinel,
      (reason: unknown) => reason
    );
    const first = seen[0];
    return {
      count: seen.length,
      first,
      isError: first instanceof Error,
      message: first?.message,
      hasCause: first instanceof Error && 'cause' in first,
      cause: first?.cause,
      caughtSame: Object.is(caught, thrown),
    };
  };

  it('wraps non-Error rejections with cause and passes an Error instance through unchanged', async () => {
    const upstreamFailure = {code: 503, detail: 'upstream down'};
    const circular: Record<string, unknown> = {};
    circular.self = circular;
    const originalError = new Error('already an error');

    const stringTurn = await observeRejection('string boom');
    const objectTurn = await observeRejection(upstreamFailure);
    const voidTurn = await observeRejection(undefined);
    const circularTurn = await observeRejection(circular);
    const errorTurn = await observeRejection(originalError);

    expect({
      string: {
        count: stringTurn.count,
        isError: stringTurn.isError,
        message: stringTurn.message,
        causeSame: Object.is(stringTurn.cause, 'string boom'),
        caughtSame: stringTurn.caughtSame,
      },
      object: {
        count: objectTurn.count,
        isError: objectTurn.isError,
        message: objectTurn.message,
        causeSame: Object.is(objectTurn.cause, upstreamFailure),
        caughtSame: objectTurn.caughtSame,
      },
      voidCase: {
        count: voidTurn.count,
        isError: voidTurn.isError,
        message: voidTurn.message,
        hasCause: voidTurn.hasCause,
        causeSame: Object.is(voidTurn.cause, undefined),
        caughtSame: voidTurn.caughtSame,
      },
      circular: {
        count: circularTurn.count,
        isError: circularTurn.isError,
        message: circularTurn.message,
        causeSame: Object.is(circularTurn.cause, circular),
        caughtSame: circularTurn.caughtSame,
      },
      errorInstance: {
        count: errorTurn.count,
        sameInstance: errorTurn.first === originalError,
        caughtSame: errorTurn.caughtSame,
      },
    }).toEqual({
      string: {
        count: 1,
        isError: true,
        message: 'string boom',
        causeSame: true,
        caughtSame: true,
      },
      object: {
        count: 1,
        isError: true,
        message: '{"code":503,"detail":"upstream down"}',
        causeSame: true,
        caughtSame: true,
      },
      voidCase: {
        count: 1,
        isError: true,
        message: 'undefined',
        hasCause: true,
        causeSame: true,
        caughtSame: true,
      },
      circular: {
        count: 1,
        isError: true,
        message: '[object Object]',
        causeSame: true,
        caughtSame: true,
      },
      errorInstance: {
        count: 1,
        sameInstance: true,
        caughtSame: true,
      },
    });
  });
});

